'use strict';
state.exploration??={bridge:false,seal:false,beacon:false,nell:false,cache:false};
ExpansionWorld.apply(worlds,state.exploration);
function applyBlessing(){for(const [k,n]of Object.entries({berries:3,log:3,crystals:2,fish:3}))resourceInfo[k].amount=n+(state.exploration.beacon?1:0);}
applyBlessing();
let runLatched=false;
const journeyQuest=questText;questText=function(){if(!state.met||!state.caught)return journeyQuest();if(!state.exploration.bridge)return 'Restore the eastern bridge · Emberkin + 12 wood';if(!state.exploration.seal)return 'Find Lunamoth, then open the riverbank cavern';if(!state.exploration.beacon)return 'Awaken the cavern beacon · 5 moon crystals';return journeyQuest();};
const explorationNearest=nearest;nearest=function(){let best=explorationNearest(),distance=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>['bridge','seal','beacon','cache','campfire'].includes(o.type))){const d=Math.hypot(o.x-player.x,o.y-player.y);if(d<distance){best=o;distance=d;}}return best;};
function expeditionAction(action){const e=state.exploration,o=nearest();if(!o||dialog===false)return false;
 if(action==='bridge'&&o.type==='bridge'&&!e.bridge&&state.wood>=12&&state.team.includes('Emberkin')){state.wood-=12;e.bridge=true;state.xp+=25;}
 else if(action==='seal'&&o.type==='seal'&&!e.seal&&state.team.includes('Lunamoth')){e.seal=true;state.xp+=25;}
 else if(action==='beacon'&&o.type==='beacon'&&!e.beacon&&state.crystals>=5){state.crystals-=5;e.beacon=true;state.coins+=120;state.xp+=50;applyBlessing();}
 else if(action==='nell'&&o.name==='Nell'&&!e.nell&&state.fish>=3){state.fish-=3;state.coins+=45;e.nell=true;}
 else return false;
 ExpansionWorld.apply(worlds,e);GameAudio.sfx('success');close();save();hud();toast({bridge:'Emberkin helps lay the final beam. The riverbank is open!',seal:'Lunamoth lights the runes. The cavern opens.',beacon:'Beacon awakened! +120 coins. All gathering yields +1.',nell:'Nell shares 45 coins and points toward a chest southwest.'}[action]);return true;
}
const expeditionInteract=interact;interact=function(){if(dialog||transitioning)return;const o=nearest();if(o&&!activity){faceTarget(o);const e=state.exploration;
 if(o.type==='bridge'){show('A bridge to somewhere new',`<p>${e.bridge?'The bridge is sturdy again. Follow the planks east to the Whispering Riverbank.':'A storm washed away the old bridge. Emberkin can help carry beams while you rebuild.'}</p>${e.bridge?'':`<p>${state.team.includes('Emberkin')?'✓':'○'} Emberkin befriended<br>${Math.min(12,state.wood)}/12 wood</p><div class="actions"><button data-expedition="bridge" ${state.team.includes('Emberkin')&&state.wood>=12?'':'disabled'}>Repair the bridge</button></div>`}<div class="actions"><button data-ui="close">Back to the trail</button></div>`,'The river trail');GameAudio.sfx('tap');return;}
 if(o.type==='seal'){show('A door written in moonlight',`<p>${e.seal?'Lunamoth’s light lingers on the open doorway. Walk north into the cavern.':'The stone door has no handle. Its faded symbols resemble Lunamoth’s wings. Befriend Lunamoth in Moonleaf Grove, then return.'}</p>${e.seal?'':`<div class="actions"><button data-expedition="seal" ${state.team.includes('Lunamoth')?'':'disabled'}>Ask Lunamoth to help</button></div>`}<div class="actions"><button data-ui="close">Leave the entrance</button></div>`,'Companion ability');return;}
 if(o.type==='beacon'){show('The valley’s sleeping light',`<p>${e.beacon?'The beacon shines again. Its blessing adds one extra item to every gathering action.':'Five moon crystals will rekindle this ancient beacon. Its blessing adds one extra item each time you gather.'}</p>${e.beacon?'':`<p>Moon crystals: ${state.crystals}/5 · Reward: 120 coins + gathering blessing</p><div class="actions"><button data-expedition="beacon" ${state.crystals>=5?'':'disabled'}>Awaken the beacon</button></div>`}<div class="actions"><button data-ui="close">Return to the cavern</button></div>`,'A light worth finding');return;}
 if(o.name==='Nell'){show('Nell, the river fisher',`<p>“${e.nell?'That was a lovely catch. If you haven’t found it, my old supply chest is southwest of camp. Help yourself.':'The river’s lively today, but my basket is empty. Bring me three fish and I’ll trade you 45 coins. Cast by the bank and wait for the bite!'}”</p>${e.nell?'':`<p>You have ${state.fish}/3 fish.</p><div class="actions"><button data-expedition="nell" ${state.fish>=3?'':'disabled'}>Trade 3 fish</button></div>`}<div class="actions"><button data-ui="close">See you by the river</button></div>`,'Riverbank request');return;}
 if(o.type==='cache'){if(!e.cache){e.cache=true;state.coins+=50;state.berries+=5;GameAudio.sfx('success');toast('Hidden supplies: +50 coins and +5 berries!');save();hud();}else toast('You have already collected these supplies.');return;}
 if(o.type==='campfire'){show('Take a breath',`<p>The fire crackles beside the river. Your companions settle into the warm grass.</p><p>${e.beacon?'The cavern beacon is glowing again. A good day’s adventure.':'The ancient cavern lies north of here. Look for the stone arch.'}</p><div class="actions"><button data-extra="audio">Music & sound</button><button data-ui="close">Back to exploring</button></div>`,'Riverbank camp');return;}}
 const before=activity;expeditionInteract();if(!before&&activity)GameAudio.sfx({log:'chop',crystals:'mine',fish:'fish',berries:'pick'}[activity.o.type]);else if(dialog)GameAudio.sfx('tap');};
const expeditionComplete=completeActivity;completeActivity=function(){const type=activity?.o.type;expeditionComplete();if(type)GameAudio.sfx({log:'chop',crystals:'mine',fish:'fish',berries:'pick'}[type]);};
const expeditionTick=tickActivities;tickActivities=function(dt){const a=activity,old=a?.elapsed;expeditionTick(dt);if(a&&activity===a){if(a.o.type==='fish'&&old<a.duration&&a.elapsed>=a.duration)GameAudio.sfx('bite');if(['log','crystals'].includes(a.o.type)&&Math.floor(old/.55)!==Math.floor(a.elapsed/.55))GameAudio.sfx(a.o.type==='log'?'chop':'mine');}};
const expeditionSocial=socialChoice;socialChoice=function(choice){const trust=encounter?.trust;expeditionSocial(choice);if(encounter)GameAudio.sfx(encounter.trust>trust?'pick':'wrong');};
const expeditionChange=changeArea;changeArea=function(p){GameAudio.sfx('door');expeditionChange(p);};
const expeditionGround=ground;ground=function(x,y,t){const px=x*T,py=y*T;if(t==='bridgefloor'){rr(px,py,32,32,'#90704b');for(let j=0;j<32;j+=8){rr(px+1,py+j,30,6,'#c1a16a');rr(px+5,py+j+2,2,2,'#715a43');}return;}if(t==='sand'){rr(px,py,32,32,'#d6c791');rr(px+(x*7)%22,py+12,3,2,'#c0af7a');rr(px+9,py+25,4,1,'#eee0ae');return;}if(t==='cavefloor'||t==='cavepath'||(map.id==='cavern'&&t==='wall')){rr(px,py,32,32,t==='wall'?'#344954':t==='cavepath'?'#63747a':'#4c606b');rr(px+3,py+12,8,2,'#3c535f');rr(px+21,py+25,7,2,'#7b8b8b');if(t==='wall'){rr(px+1,py+2,29,10,'#546975');rr(px+2,py+16,24,8,'#425c69');}return;}expeditionGround(x,y,t);};
const expeditionObject=object;object=function(o){const x=o.x,y=o.y;if(o.type==='wildflowers'){for(let i=0;i<9;i++){const fx=x-16+(i*11)%33,fy=y-11+(i*7)%22;rr(fx,fy,2,6,'#4b814a');rr(fx-2,fy-3,5,4,i%2?'#e8d79c':'#d9b5c1');}return;}if(o.type==='reeds'){for(let i=0;i<6;i++){rr(x-12+i*5,y-17-(i%3)*3,2,26,'#67865a');rr(x-12+i*5,y-20-(i%3)*3,3,9,'#a39060');}return;}if(o.type==='bridge'){rr(x-5,y-17,5,25,'#786047');rr(x-14,y-27,25,15,'#c4a66f');text(state.exploration.bridge?'→':'!',x-1,y-16,'#453e33',12);return;}if(o.type==='caveEntrance'){rr(x-75,y-50,150,82,'#6c7974');rr(x-59,y-66,118,89,'#8a9381');rr(x-29,y-35,58,67,'#1d3540');rr(x-34,y-44,68,12,'#acb19b');rr(x-66,y-20,24,3,'#55665f');rr(x+42,y+6,22,3,'#55665f');if(!state.exploration.seal){rr(x-13,y-2,27,32,'#697b83');text('✧',x,y+20,'#b5c1de',19);}return;}if(o.type==='seal'){if(!state.exploration.seal){rr(x-7,y-13,14,18,'#81939a');rr(x-3,y-20,6,24,'#c0c6e3');}return;}if(o.type==='boulder'){rr(x-17,y-17,35,22,'#324c57');rr(x-12,y-26,25,27,'#72858c');rr(x-8,y-23,12,4,'#94a2a3');return;}if(o.type==='beacon'){rr(x-22,y-1,44,10,'#8d9b97');rr(x-15,y-26,30,29,'#718786');rr(x-10,y-44,20,20,state.exploration.beacon?'#eddfa0':'#8c9fa9');if(state.exploration.beacon){for(let i=0;i<5;i++)rr(x+Math.sin(clockTime+i)*25,y-34-Math.abs(Math.cos(clockTime*.8+i))*24,2,3,'#f4e4b5');}text('Ancient beacon',x,y+22,'#e5e9cc',9);return;}if(o.type==='campfire'){rr(x-14,y-3,29,9,'#746b56');rr(x-10,y-1,21,3,'#b59866');rr(x-7,y-17,15,17,'#d4814d');rr(x-3,y-23+Math.sin(clockTime*6)*3,7,21,'#ebcf76');return;}if(o.type==='cache'){expeditionObject({...o,type:'chest'});if(state.exploration.cache)rr(x-10,y-19,21,9,'#493f31');return;}expeditionObject(o);};
const expeditionHUD=interactionHUD;interactionHUD=function(){expeditionHUD();if(!activity&&near){const verbs={bridge:'Repair',seal:'Open',beacon:'Light',cache:'Search',campfire:'Rest'};if(verbs[near.type]){document.getElementById('action').innerHTML=verbs[near.type]+'<small>E / A</small>';document.getElementById('near').textContent={bridge:'The old river bridge',seal:'Moonlit stone seal',beacon:'Ancient beacon',cache:'Hidden supply chest',campfire:'Riverside camp'}[near.type];}}};
function journal(){const e=state.exploration;show('Trails worth following',`<div class="trail-list"><p><b>Willowmere Valley</b><br>North: Moonleaf Grove · East: Sunlit Meadow<br>Cottage in the northwest · Homestead northeast</p><p><b>Sunlit Meadow</b><br>Emberkin in the southern grass · Dewdrop by the pond<br>East: ${e.bridge?'Whispering Riverbank':'broken bridge — Emberkin + 12 wood'}</p><p><b>Whispering Riverbank</b><br>Nell by the eastern shore · Supply chest southwest<br>North: ${e.seal?'Lantern Cavern':'sealed cavern — bring Lunamoth'}</p><p><b>Lantern Cavern</b><br>${e.beacon?'✓ Beacon restored · +1 to all gathering':'Offer 5 crystals to awaken the beacon'}</p></div><div class="actions"><button data-ui="close">Back to exploring</button></div>`,'World guide');}
function audioMenu(){const p=GameAudio.settings;show('The sound of the valley',`<p>Original mellow piano chords, a soft bass line and a brushed beat. Music pauses when the game is in the background.</p><div class="actions"><button data-extra="music">${p.music?'Pause music':'Play music'}</button><button data-extra="effects">Sounds: ${p.effects?'on':'off'}</button></div><label class="volume-label">Music volume <input aria-label="Music volume" id="music-volume" type="range" min="0" max="100" value="${Math.round(p.volume*100)}"></label><p class="audio-note">${GameAudio.status.available?'Music is optional. Headphones recommended.':'Audio is not supported in this browser.'}</p><div class="actions"><button data-ui="close">Back to the valley</button></div>`,'Music & sound');}
help=function(){show('Pause for a moment',`<p>Move with the joystick or WASD. Walk close to something, then use the action button or E. Tap Run to keep running; tap again to walk.</p><div class="actions"><button data-extra="journal">World guide</button><button data-extra="audio">Music & sound</button><button data-extra="fullscreen">Full screen</button></div><p>Repair the meadow bridge, discover the riverbank, and rekindle the cavern beacon. Your companions can open paths you cannot.</p><div class="actions"><button data-ui="close">Continue adventure</button></div>`,'Mosswild');};
app.addEventListener('click',async e=>{const b=e.target.closest('[data-extra],[data-expedition]');if(!b||b.disabled)return;if(b.dataset.expedition){expeditionAction(b.dataset.expedition);return;}switch(b.dataset.extra){case 'journal':journal();break;case 'audio':audioMenu();break;case 'music':if(await GameAudio.setMusic(!GameAudio.settings.music))audioMenu();else toast('Sound could not start. Try another browser.');break;case 'effects':await GameAudio.unlock();GameAudio.setEffects(!GameAudio.settings.effects);audioMenu();break;case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await app.requestFullscreen();close();}catch{toast('Full screen is unavailable here. Landscape mode gives more room.');}break;}});
app.addEventListener('input',e=>{if(e.target.id==='music-volume')GameAudio.setVolume(Number(e.target.value)/100);});
app.addEventListener('pointerdown',()=>{void GameAudio.unlock();},{once:true});addEventListener('keydown',()=>{void GameAudio.unlock();},{once:true});
addEventListener('keydown',e=>{if(e.key.toLowerCase()==='m'&&!dialog)journal();});
app.addEventListener('click',e=>{if(e.target.closest('[data-ui="befriend"]'))GameAudio.sfx('success');});
const soundButton=document.createElement('button');soundButton.className='wood sound-button';soundButton.dataset.extra='audio';soundButton.textContent='♫';soundButton.setAttribute('aria-label','Music and sound');document.querySelector('.hud-right').append(soundButton);
document.querySelector('[data-ui="help"]').textContent='Menu';document.querySelector('[data-ui="help"]').setAttribute('aria-label','Game menu');document.querySelector('[data-ui="bag"]').textContent='Bag';document.querySelector('.hint').textContent=matchMedia('(pointer:coarse)').matches?'Drag to move · tap Run to sprint · tap action to interact':'WASD / arrows · E interact · Shift run · M world guide';
